<span class="line"><span class="token keyword">def</span> 步长设定函数<span class="token punctuation">(</span>分割<span class="token punctuation">,</span> step<span class="token operator">=</span><span class="token punctuation">(</span><span class="token number">0.5</span><span class="token operator">+</span><span class="token number">0.1</span><span class="token operator">-</span><span class="token number">0.2</span><span class="token operator">+</span><span class="token number">0.1</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">:</span></span>
